ALTER TABLE "execution_commands" ADD CONSTRAINT "execution_commands_transport_state_check" CHECK ("execution_commands"."transport_state" in ('not_sent', 'dispatching', 'acknowledged', 'unknown', 'reconciliation_required'));--> statement-breakpoint
ALTER TABLE "execution_commands" ADD CONSTRAINT "execution_commands_application_state_check" CHECK ("execution_commands"."application_state" in ('pending', 'applying', 'applied', 'superseded', 'poisoned'));--> statement-breakpoint
-- Preserve an existing applied marker without inventing a request snapshot.
UPDATE "execution_commands" SET "application_state" = 'applied'
WHERE "completion_applied_at" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "execution_commands" ADD CONSTRAINT "execution_commands_application_shape_check" CHECK (
      ("execution_commands"."application_state" = 'applied') = ("execution_commands"."completion_applied_at" IS NOT NULL)
      AND ("execution_commands"."application_state" = 'applying') = ("execution_commands"."application_claim_owner" IS NOT NULL AND "execution_commands"."application_claim_expires_at" IS NOT NULL)
      AND ("execution_commands"."application_claim_owner" IS NULL) = ("execution_commands"."application_claim_expires_at" IS NULL)
      AND "execution_commands"."application_attempts" >= 0
      AND ("execution_commands"."application_state" != 'poisoned' OR "execution_commands"."application_next_retry_at" IS NULL));
--> statement-breakpoint
CREATE FUNCTION "guard_immutable_command_request"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.request_schema = 'maister.command.request.v2' AND
    ROW(NEW.id, NEW.run_id, NEW.execution_assignment_id, NEW.execution_host_id,
        NEW.assignment_epoch, NEW.kind, NEW.target_session_id, NEW.created_at,
        NEW.owner_kind, NEW.owner_ref, NEW.logical_operation_key,
        NEW.request_schema, NEW.request_sha256, NEW.request_canonical_json)
    IS DISTINCT FROM
    ROW(OLD.id, OLD.run_id, OLD.execution_assignment_id, OLD.execution_host_id,
        OLD.assignment_epoch, OLD.kind, OLD.target_session_id, OLD.created_at,
        OLD.owner_kind, OLD.owner_ref, OLD.logical_operation_key,
        OLD.request_schema, OLD.request_sha256, OLD.request_canonical_json)
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'execution_commands_immutable_request',
      MESSAGE = 'admitted command request and owner are immutable';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "execution_commands_immutable_request"
BEFORE UPDATE OF id, run_id, execution_assignment_id, execution_host_id,
  assignment_epoch, kind, target_session_id, created_at, owner_kind, owner_ref,
  logical_operation_key, request_schema, request_sha256, request_canonical_json
ON "execution_commands"
FOR EACH ROW EXECUTE FUNCTION "guard_immutable_command_request"();
